=== submission_07.ino ===
   1| // Lab 3 -- 1kHz 25% PWM on D5 with the PWM peripheral
   2| //
   3| // pin:  D5 is P1.13 -> PSEL port 1, pin 13
   4| // clk:  16MHz / 16 = 1MHz
   5| // top:  1MHz / 1kHz = 1000
   6| // duty: 1000 / 4 = 250, OR'd with 0x8000 for active-high
   7| //
   8| // seq A = SEQ[0], seq B = SEQ[1]. only one sequence needed.
   9| 
  10| #include <Arduino.h>
  11| 
  12| uint16_t duty_seq[] = { 250 | 0x8000 };
  13| 
  14| void pwm_init(void) {
  15|   NRF_PWM0->PSEL.OUT[0] = (1 << PWM_PSEL_OUT_PORT_Pos) | (13 << PWM_PSEL_OUT_PIN_Pos);
  16|   NRF_PWM0->ENABLE      = PWM_ENABLE_ENABLE_Enabled << PWM_ENABLE_ENABLE_Pos;
  17|   NRF_PWM0->MODE        = PWM_MODE_UPDOWN_Up << PWM_MODE_UPDOWN_Pos;
  18|   NRF_PWM0->PRESCALER   = PWM_PRESCALER_PRESCALER_DIV_16 << PWM_PRESCALER_PRESCALER_Pos;
  19|   NRF_PWM0->COUNTERTOP  = 1000;
  20|   NRF_PWM0->LOOP        = 0;
  21|   NRF_PWM0->DECODER     = (PWM_DECODER_LOAD_Common << PWM_DECODER_LOAD_Pos) |
  22|                           (PWM_DECODER_MODE_RefreshCount << PWM_DECODER_MODE_Pos);
  23| 
  24|   NRF_PWM0->SEQ[0].PTR      = (uint32_t)duty_seq;
  25|   NRF_PWM0->SEQ[0].CNT      = 1;
  26|   NRF_PWM0->SEQ[0].REFRESH  = 0;
  27|   NRF_PWM0->SEQ[0].ENDDELAY = 0;
  28| }
  29| 
  30| void pwm_start(void) {
  31|   NRF_PWM0->TASKS_SEQSTART[1] = 1;
  32| }
  33| 
  34| void setup() {
  35|   pwm_init();
  36|   pwm_start();
  37| }
  38| 
  39| void loop() {
  40| }
</student_code>
